/* ARSONMIX GLOBAL HARDWARE KEY V1 — owner approved MUTE/SOLO material.
   This is one reusable material token, NOT a new button geometry/layout.
   Never apply to circular WIRE connectors, fader thumb, meter LEDs, sliders,
   section-rail disclosures, or drag targets. All colors are semantic variants.
   No animations, filters, textures, permanent pressed state, or extra JS. */

/* A single mechanical face for every ordinary PUSH button; retain existing
   29px header / strip widths and accessibility semantics. New buttons opt
   in with .hw-key instead of inheriting unexpected styling on rotary/jacks. */
:is(
 .command-bar button.tool,
 .command-bar summary.tool,
 .more-tools-panel button.tool,
 .console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,
 .plugin-footer button,
 .route-choice-head button,
 .route-choice-option,
 button.hw-key
){
 position:relative!important;
 border:1px solid var(--am-hw-key-border)!important;
}
/* EXACT top/bottom edge glints: no inset offset on the key face. The whitened
   core fades horizontally to transparent at both ends. */
:is(
 .command-bar button.tool,.command-bar summary.tool,
 .more-tools-panel button.tool,.console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
)::before{
 content:""!important;position:absolute!important;pointer-events:none!important;
 border:0!important;box-shadow:none!important;opacity:1!important;
}
:is(
 .command-bar button.tool,.command-bar summary.tool,
 .more-tools-panel button.tool,.console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
)::after{
 content:""!important;position:absolute!important;pointer-events:none!important;
 border:0!important;box-shadow:none!important;opacity:1!important;
}
/* The key actually sinks into the surrounding socket only during touch/click.
   A latched MUTE/SOLO remains raised, changing ONLY semantic color. */
:is(
 .command-bar button.tool,.command-bar summary.tool,
 .more-tools-panel button.tool,.console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
):active:not(:disabled){
 filter:none!important;
}
:is(
 .command-bar button.tool,.command-bar summary.tool,
 .more-tools-panel button.tool,.console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
):focus-visible{
 outline:2px solid #9ceaff!important;outline-offset:2px!important;
}
:is(
 .command-bar button.tool,.command-bar summary.tool,
 .more-tools-panel button.tool,.console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
):disabled{
 opacity:.5!important;cursor:not-allowed!important;
}
/* Family colorways only. Physical edges and shadows are shared unchanged. */
.command-bar button.tool,
.command-bar summary.tool,
.more-tools-panel button.tool,.command-bar button.tool:is(.active,[aria-pressed="true"]),
.command-bar summary.tool[aria-expanded="true"],
.more-tools[open] summary.tool{
 --am-hw-key-face:#6498a9;
 --am-hw-key-ink:#081b23;
 --am-hw-key-border:#6ca5b5;
}
@media(prefers-reduced-motion:reduce){
 :is(.command-bar .tool,.console-body .switch-section .switch,.route-choice-option,button.hw-key){
  transition:none!important;
 }
}
.routing-wire-overlay{filter:none!important}



/* V18 HARDWARE KEY SOCKET + CRISP LED METER — owner visual audit, 2026-11-02.
   Material token stays global. The body is a real recessed mounting well:
   dark 1px machined cut, light 1px metal lip, cap stands 1px above its well.
   Only semantic color differs between controls; no blurred shadows, filters,
   backdrop filters, RAF style recalculation or extra LED DOM nodes. */

/* A recessed common switch bay is machined into the STRIP panel, not
   painted halfway across the top face. Housing never moves with buttons. */
.console-body .strip .switch-section {
 position:relative!important;
 isolation:isolate;
}
.console-body .strip .switch-section button.switch{
 z-index:1!important;
 border-radius:var(--am-hw-key-radius)!important;
 box-shadow:var(--am-hw-key-relief)!important;
}
/* Every hardware PUSH key shares the same outer socket, sharp relief and
   very shallow mechanical travel. Do not flatten latched MUTE/SOLO. */
:is(.command-bar button.tool,.command-bar summary.tool,
 .more-tools-panel button.tool,.console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key){
 will-change:auto!important;
}
/* Edge highlights stay on the exact face edges, horizontally translucent
   at the corners; the lower glint is intentionally thinner. */
:is(.command-bar button.tool,.command-bar summary.tool,
 .more-tools-panel button.tool,.console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key)::before{
}
/* Remove convolution-style glow and blur work. All depth comes from
   1px crisp borders, embossed edges, static face gradients, native textures. */
html * ,html *::before,html *::after{
 filter:none!important;
 backdrop-filter:none!important;
 -webkit-backdrop-filter:none!important;
}
.plugin-browser,.channel-identity,.route-choice,.more-tools-panel{
 box-shadow:0 0 0 1px #60717b,0 1px 0 1px #07141b!important;
}


/* V19 FUTURE-CONSOLE KEY MATERIAL — graphite + restrained status illumination.
   Visual inspiration: dark hardware surfaces, jewel status keys and tightly
   machined sockets on modern large-format digital mixing consoles.
   Shared material: same 2px square-rounded cap, 1px press, one chrome
   edge-light recipe, NO diffuse shadows, blur, filter, animations, or DOM. */

/* Important: one real physical material for push-buttons. Layout stays put. */
:is(.command-bar button.tool,.command-bar summary.tool,
 .more-tools-panel button.tool,.console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key){
 color:var(--am-hw-key-ink)!important;
 border-color:var(--am-hw-key-border)!important;
 text-shadow:0 1px 0 rgba(0,0,0,.23)!important;
}

/* A deliberate narrow white reflection ON THE EDGE, never in the middle. */


/* Graphite OFF, colored ON — same geometry. No always-on glow. */
.command-bar button.tool,
.command-bar summary.tool,
.more-tools-panel button.tool,
.route-choice-head button {
 --am-hw-key-ink:#e2ecf0;
 --am-hw-key-border:#647783;
}
.command-bar button.tool:is(.active,.primary,[aria-pressed="true"]),
.command-bar summary.tool[aria-expanded="true"],
.more-tools[open] summary.tool {
 --am-hw-key-ink:#f3fcff;
 --am-hw-key-border:#6fb3c2;
}
.console-body .strip .switch-section button.switch:not(.on) {
 --am-hw-key-ink:#e4edf0;
 --am-hw-key-border:#72838c;
}
.console-body .strip .switch-section button.switch.on.mute {
 text-shadow:0 -1px 0 rgba(56,0,9,.5)!important;
}
.console-body .strip .switch-section button.switch.on.solo {
 text-shadow:0 1px 0 rgba(255,255,255,.2)!important;
}
.route-choice-option.primary{
 --am-hw-key-ink:#f0fff9;
 --am-hw-key-border:#6ac6a3;
}
#identitySave {
 --am-hw-key-ink:#f2fcff;
 --am-hw-key-border:#7ed4e1;
}
/* Socket bezel belongs to the console, not floating in the button face. *//* Keep every control crisp on modest GPU hardware. */

/* V20 CUBE/ILLUMINATED HARDWARE KEY — single material extension, zero blur.
   Face appears internally backlit; three crisp unblurred sidewall lines
   plus a dark socket convey cube depth. Press is precisely 1px. */

/* The same cap surface for ALL push-buttons: near-vertical satin
   highlight, colored lens middle, dark lower skirt, sharp edge. */
:is(.command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key){
 --am-hw-key-press-y:1px;
 user-select:none!important;-webkit-user-select:none!important;
 border-radius:2px!important;
 transform:translateY(0)!important;
}
:is(.command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key)::before{
 top:0!important;left:1px!important;right:1px!important;height:2px!important;
 background:var(--am-hw-key-upper-glint)!important;
}
:is(.command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section button.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key)::after{
 bottom:0!important;left:2px!important;right:2px!important;height:1px!important;
 background:var(--am-hw-key-lower-glint)!important;
}
/* Machined socket behind keycaps, not light bleeding onto the chassis. *//* Off and on use same geometry. Only optical material tokens change. */
.command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
.route-choice-head button{
 --am-hw-key-face:#374c58;--am-hw-key-bright:#5c7582;
 --am-hw-key-deep:#1a2b35;--am-hw-key-wall:#1c303b;
}
.command-bar button.tool:is(.active,.primary,[aria-pressed="true"]),
.command-bar summary.tool[aria-expanded="true"],.more-tools[open] summary.tool{
 --am-hw-key-face:#2d7386;--am-hw-key-bright:#71c3d8;
 --am-hw-key-deep:#153e4a;--am-hw-key-wall:#1b5060;
}
.console-body .strip .switch-section button.switch:not(.on){
 --am-hw-key-face:#405360;--am-hw-key-bright:#586c79;
 --am-hw-key-deep:#202f39;--am-hw-key-wall:#1d2c35;
}
.console-body .strip .switch-section button.switch.on.mute{
 --am-hw-key-face:#ae3346;--am-hw-key-bright:#f26e7c;
 --am-hw-key-deep:#581e2b;--am-hw-key-wall:#611e2c;
 --am-hw-key-ink:#fff7f8;--am-hw-key-border:#eb7380;
}
.console-body .strip .switch-section button.switch.on.solo{
 --am-hw-key-face:#bc8f2e;--am-hw-key-bright:#ffe08a;
 --am-hw-key-deep:#654811;--am-hw-key-wall:#715520;
 --am-hw-key-ink:#261d09;--am-hw-key-border:#f4d370;
}
.console-body .strip .switch-section button.switch.on.cue{
 --am-hw-key-face:#2a879e;--am-hw-key-bright:#79d8ed;
 --am-hw-key-deep:#134458;--am-hw-key-wall:#185468;
 --am-hw-key-ink:#f4fdff;--am-hw-key-border:#7fd7e8;
}
.route-choice-option.primary{
 --am-hw-key-face:#327b64;--am-hw-key-bright:#7fdec0;
 --am-hw-key-deep:#164b3c;--am-hw-key-wall:#185341;
}
#identitySave{
 --am-hw-key-face:#2d8597;--am-hw-key-bright:#80d5e7;
 --am-hw-key-deep:#174757;--am-hw-key-wall:#185468;
}
/* Explicitly no optical postprocessing / blur / expensive animation. */
:is(.command-bar,.console-body,.plugin-browser,.route-choice) button{
 filter:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;
}

